message.content:
{
  "pitches": [
    {
      "key": "sao_argo_small_trade",
      "title": "아르고의 파편화된 정보",
      "premise": "아르고에게 특정 지역의 지형 정보를 물었으나 답변이 너무 방대해 핵심을 파악하기 어렵다. 정보상인과 구매자 사이의 의사소통에 혼선이 생긴다. 나는 답변의 범위를 좁히기 위해 구체적인 질문을 던지거나 필요한 정보의 우선순위를 정해야 한다.",
      "choices": [
        "특정 지형이 아닌, 그 지형에서 마주칠 가능성이 높은 몬스터의 종류만 우선적으로 묻는다.",
        "답변이 끝날 때까지 경청한 뒤, 그중 내가 당장 이동해야 할 경로에 해당하는 부분만 발췌한다.",
        "정보의 대가로 지불할 골드를 조정하며, 내가 지금 당장 필요한 '가장 가까운 보급로' 하나만 다시 묻는다."
      ],
      "basis": "아르고에게 너무 넓은 질문을 해 답의 범위가 어긋나는 작은 정보 거래."
    },
    {
      "key": "sao_argo_monopoly_complaint",
      "title": "정보의 독점과 관찰",
      "premise": "아르고가 두 명의 손님에게 동일한 정보를 판매하자, 자신이 먼저 들었다고 생각한 플레이어가 항의한다. 분위기가 험악해지며 정보의 가치에 대한 논쟁이 발생한다. 나는 타인의 권리를 침해하지 않으면서 내 정보 획득의 목적을 달성해야 한다.",
      "choices": [
        "항의하는 플레이어에게 양해를 구하고, 나는 아르고에게 추가적인 '주변 지형의 위험도'를 별도로 묻는다.",
        "논쟁에 휘말리지 않고 아르고에게 현재 내가 파악한 정보와 대조할 수 있는 다른 카드 후보를 요청한다.",
        "상대방의 항의를 무시하는 대신, 아르고에게 정보의 정확성을 재확인해달라고 요청하며 내 구매를 진행한다."
      ],
      "basis": "아르고가 두 손님에게 같은 정보를 팔자 독점이라고 생각했던 사람이 항의한다."
    },
    {
      "key": "sao_girl_small_task",
      "title": "소녀를 위한 작은 손길",
      "premise": "호숫가 근처에서 기억을 잃은 소녀에게 사람들이 한꺼번에 질문을 쏟아내며 소녀가 당황하고 있다. 질문들은 소녀에게 큰 부담이 되고 있으며 주변 분위기는 어수선하다. 나는 소녀의 기억을 억지로 되찾으려 하지 않고 현장에서 할 수 있는 작은 도움을 골라야 한다.",
      "choices": [
        "사람들의 시선을 돌리기 위해 주변의 나무를 정리하거나 길을 터주는 등의 단순 노동을 자처한다.",
        "소녀에게 질문을 던지는 대신, 소녀가 안정을 취할 수 있도록 근처에 앉아 조용히 주변을 경계한다.",
        "소녀에게 필요한 물건이 있는지 묻고, 주변 사람들에게 물건을 가져다달라고 부탁하며 상황을 분산시킨다."
      ],
      "basis": "통나무집 부근에서 기억을 잃은 소녀에게 사람들이 질문을 한꺼번에 건네 답을 기다리는 장면."
    },
    {
      "key": "sao_pair_first_step",
      "title": "엇갈리는 첫걸음",
      "premise": "디아벨의 회의 이후 두 명의 솔로 플레이어가 파티를 맺기로 했으나, 이동 경로와 준비물 확인에서 의견이 엇갈린다. 서로의 스타일이 달라 첫 발걸음부터 마찰이 생긴다. 나는 파티의 목표를 해치지 않으면서 내 위치와 준비를 확정해야 한다.",
      "choices": [
        "내가 먼저 확보한 보급품 리스트를 공유하고, 상대방이 원하는 경로를 우선적으로 수용한다.",
        "현재 내 위치에서 가장 안전한 경로를 제안하고, 상대방의 동의를 얻은 뒤 이동을 시작한다.",
        "상대방의 속도에 맞추기로 하고, 내가 챙긴 장비 중 상대가 필요할 만한 것을 먼저 꺼내어 확인한다."
      ],
      "basis": "디아벨의 공략 회의 뒤 서로 혼자 다니던 두 사람이 한 파티가 되려는데 첫 발걸음부터 엇갈린다."
    },
    {
      "key": "sao_kirito_reason_trade",
      "title": "무상 도움의 대화",
      "premise": "키리토가 시리카를 무상으로 도와주겠다고 하자, 주변 사람들이 그 이유를 궁금해하며 시선이 집중된다. 여행자인 나는 키리토의 의도를 캐묻기보다 현재 상황에서 필요한 보급과 행동에 집중해야 한다. 원작의 대답을 추측하지 않고 내 행동으로 대화를 이어간다.",
      "choices": [
        "키리토의 호의에 감사함을 표하며, 내가 가진 소모성 아이템 중 하나를 나누어 주는 것으로 화답한다.",
        "이유를 묻는 대신, 지금 당장 시리카에게 필요한 구체적인 보급품 목록을 작성하여 키리토에게 전달한다.",
        "키리토의 제안을 수용하고, 나는 다음 이동 경로에서 마주칠 수 있는 장애물을 미리 파악하는 업무를 맡는다."
      ],
      "basis": "시리카가 무상으로 도와주겠다는 키리토의 말을 듣고도 이유를 묻는 장면."
    },
    {
      "key": "sao_daily_campfire",
      "title": "밤의 모닥불과 휴식",
      "premise": "긴 탐색 끝에 캠프를 치고 모닥불 앞에 모였지만, 다음 날의 이동 경로와 역할 분담에 대한 의견이 갈린다. 전투가 없는 일상적인 상황이지만 효율적인 휴식을 위해 정리가 필요하다. 나는 영웅적인 결단이 아닌, 내일의 체력을 보존하기 위한 실무적인 행동을 골라야 한다.",
      "choices": [
        "내일 사용할 식량과 물을 미리 분류해두고, 밤새 주변의 소리를 모니터링하는 역할을 맡는다.",
        "모닥불 주변의 짐을 정리하고, 다음 날 이동 시 가장 먼저 확인해야 할 체크리스트를 작성한다.",
        "동료들의 장비 상태를 가볍게 확인하며, 내일 이동 경로 중 가장 험한 구간에 대한 정보를 공유한다."
      ],
      "basis": "첫5개와 기존 사건에서 겹치지 않는 일상 사건1개를 추가한다."
    }
  ]
}
